/** Text patches for resource and domain modules generated by `ash.gen.*`. */

/**
 * Adds lines at the end of a `name do ... end` section of a module, creating it before the module's
 * `end` when missing. With `inner`, the lines go into a section nested in it, such as `oban` > `triggers`.
 */
export function addToSection(text: string, name: string, lines: string[], inner?: string): string {
    const section = new RegExp(`\\n  ${name} do\\n([\\s\\S]*?)\\n  end\\n`);
    const match = section.exec(text);
    if (!match) {
        const body = inner ? [`${inner} do`, ...lines.map(l => `  ${l}`), 'end'] : lines;
        return text.replace(/\nend\n?$/, `\n\n  ${name} do\n${indent(body, '    ')}\n  end\nend\n`);
    }
    const separator = lines[0].endsWith(' do') ? '\n' : '';
    const content = inner ? addToInner(match[1], inner, lines) : `${match[1]}\n${separator}${indent(lines, '    ')}`;
    return text.replace(match[0], `\n  ${name} do\n${content}\n  end\n`);
}

function addToInner(content: string, inner: string, lines: string[]): string {
    const section = new RegExp(`(^|\\n)    ${inner} do\\n([\\s\\S]*?)\\n    end(?=\\n|$)`);
    const match = section.exec(content);
    if (!match) return `${content}\n\n${indent([`${inner} do`, ...lines.map(l => `  ${l}`), 'end'], '    ')}`;
    const separator = lines[0].endsWith(' do') ? '\n' : '';
    return content.replace(match[0], `${match[1]}    ${inner} do\n${match[2]}\n${separator}${indent(lines, '      ')}\n    end`);
}

function indent(lines: string[], prefix: string): string {
    return lines.map(l => (l ? prefix + l : l)).join('\n');
}

/** Adds an extension to the `use Ash.Resource` or `use Ash.Domain` options. */
export function addExtension(text: string, extension: string): string {
    const match = /use Ash\.(Resource|Domain),?[^\n]*(?:\n {4,}[^\n]*)*/.exec(text);
    if (!match || match[0].includes(extension)) return text;
    const updated = /extensions: \[/.test(match[0])
        ? match[0].replace(/extensions: \[/, `extensions: [${extension}, `)
        : `${match[0]},\n    extensions: [${extension}]`;
    return text.replace(match[0], updated);
}
